type CoverRequest={id:string;shiftId:string;instructor:string;coverage:string[];status:'PENDING'|'APPROVED'|'NOT SELECTED';createdAt:string};
type OwnCover={sessionId:number;status:'OPEN'|'FILLED';preferred?:string;covering?:string;responses:number;requestedAt?:string};type Message={id:number;from:string;title:string;body:string;time:string;unread:boolean;category:'Management'|'Covers'|'Updates';kind?:'schedule'|'cover'|'campaign'|'update';detail?:string;actionLabel?:string;ackRequired?:boolean;acknowledged?:boolean};const seedMessages:Message[]=[{id:1,from:'Barry’s Sydney',title:'October schedule is now live',body:'The October schedule has been published. Check My Schedule for your classes.',detail:'Your October teaching schedule is now live. Please review your studios, days and class times before the new schedule begins. If anything looks incorrect, contact management rather than arranging a change outside the cover workflow.',time:'12m',unread:true,category:'Management',kind:'schedule',actionLabel:'View my schedule',ackRequired:true},{id:2,from:'Covers',title:'George is covering next Friday 7:00 AM',body:'Reminder: tell your regulars who is covering next week.',detail:'George has been approved to cover your Friday 7:00 AM Martin Place class next week. Please let your regular clients know today. MyTeam will remind you again 15 minutes before class. Management will update the live Mariana Tek assignment separately.',time:'Now',unread:true,category:'Covers',kind:'cover',actionLabel:'View cover details'},{id:3,from:'Barry’s Sydney',title:'The Standard · October campaign',body:'October is about performance — the highest standard of training.',detail:'The Standard launches across the studio in October. Use the campaign language on mic and across your social content where appropriate. Management will share approved assets and key dates here so you can return to this message throughout the campaign.',time:'Yesterday',unread:false,category:'Updates',kind:'campaign',actionLabel:'View campaign'},{id:4,from:'MyTeam',title:'Your evaluation is ready',body:'Your latest development review has been published.',detail:'Your latest instructor evaluation has been published. Open Development to review your feedback, current priorities and progress from your previous review.',time:'2d',unread:false,category:'Updates',kind:'update',actionLabel:'View evaluation'}];
